<?php
declare(strict_types=1);require __DIR__.'/_bootstrap.php';
if(!in_array(strtolower((string)($currentUser['role']??'')),['superadmin','admin','organiser'],true)){header('Location:index.php');exit;}
$newsId=max(0,(int)($_GET['news_id']??$_POST['news_id']??0));$news=fetchNewsArticle($pdo,$newsId);if(!$news){header('Location:news.php');exit;}$edit=(int)($_GET['edit']??$_POST['id']??0);$section=$edit?fetchNewsSection($pdo,$edit):null;
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'save';if($action==='delete'){$pdo->prepare('DELETE FROM news_content_sections WHERE id=:id AND news_id=:news')->execute([':id'=>$edit,':news'=>$newsId]);header('Location:news_sections.php?news_id='.$newsId);exit;}$sub=trim((string)($_POST['subheading']??''));$body=trim((string)($_POST['body_html']??''));$layout=in_array($_POST['layout']??'auto',['auto','image_left','image_right','text_only'],true)?$_POST['layout']:'auto';$showOnWeb=!empty($_POST['show_on_web'])?1:0;$archived=!empty($_POST['archived'])?1:0;if($edit){$pdo->prepare('UPDATE news_content_sections SET subheading=:sub,body_html=:body,layout=:layout,display_order=:ord,show_on_web=:show,archived=:arch WHERE id=:id AND news_id=:news')->execute([':sub'=>$sub?:null,':body'=>$body?:null,':layout'=>$layout,':ord'=>(int)($_POST['display_order']??100),':show'=>$showOnWeb,':arch'=>$archived,':id'=>$edit,':news'=>$newsId]);}else{$pdo->prepare('INSERT INTO news_content_sections(news_id,subheading,body_html,layout,display_order,show_on_web,archived) VALUES(:news,:sub,:body,:layout,:ord,:show,:arch)')->execute([':news'=>$newsId,':sub'=>$sub?:null,':body'=>$body?:null,':layout'=>$layout,':ord'=>(int)($_POST['display_order']??100),':show'=>$showOnWeb,':arch'=>$archived]);}header('Location:news_sections.php?news_id='.$newsId);exit;}
$sections=fetchNewsSections($pdo,$newsId);admin_layout_start('News Content Sections','news');?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><div class="small text-muted"><?php echo h($news['headline']); ?></div><h5 class="mb-0">News Content Sections</h5></div><div><a class="btn btn-outline-secondary" href="news_edit.php?id=<?php echo $newsId; ?>">Back to News</a> <a class="btn btn-success" href="news_sections.php?news_id=<?php echo $newsId; ?>&edit=0&new=1">Add Section</a></div></div>
<?php if(isset($_GET['new'])||$section): $section=$section?:['id'=>0,'subheading'=>'','body_html'=>'','layout'=>'auto','display_order'=>100,'show_on_web'=>1,'archived'=>0]; ?><div class="card-soft p-4 mb-4"><form method="post" class="row g-3"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="id" value="<?php echo (int)$section['id']; ?>"><div class="col-12"><label class="form-label">Subheading</label><input class="form-control" name="subheading" value="<?php echo h($section['subheading']??''); ?>"></div><div class="col-12"><label class="form-label">Text</label><textarea class="form-control wysiwyg-field" rows="7" name="body_html"><?php echo h($section['body_html']??''); ?></textarea></div><div class="col-md-4"><label class="form-label">Layout</label><select class="form-select" name="layout"><?php foreach(['auto'=>'Automatic','image_left'=>'Image left','image_right'=>'Image right','text_only'=>'Text only'] as$v=>$l): ?><option value="<?php echo $v; ?>" <?php echo $section['layout']===$v?'selected':''; ?>><?php echo $l; ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Order</label><input type="number" class="form-control" name="display_order" value="<?php echo (int)$section['display_order']; ?>"></div><div class="col-md-2 form-check mt-5"><input class="form-check-input" type="checkbox" name="show_on_web" <?php echo $section['show_on_web']?'checked':''; ?>> Show</div><div class="col-md-2 form-check mt-5"><input class="form-check-input" type="checkbox" name="archived" <?php echo $section['archived']?'checked':''; ?>> Archived</div><div class="col-12"><button class="btn btn-success">Save Section</button></div></form></div><?php render_tinymce_bootstrap(); ?><script>tinymce.init(window.ildraNewsTinyMceConfig('textarea.wysiwyg-field'));</script><?php endif; ?>
<div class="card-soft p-3"><table class="table align-middle"><thead><tr><th>Order</th><th>Subheading</th><th>Layout</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($sections as$s): ?><tr><td><?php echo (int)$s['display_order']; ?></td><td><?php echo h($s['subheading']?:'Untitled section'); ?></td><td><?php echo h($s['layout']); ?></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="news_sections.php?news_id=<?php echo $newsId; ?>&edit=<?php echo (int)$s['id']; ?>">Edit</a> <a class="btn btn-sm btn-outline-primary" href="news_images.php?section_id=<?php echo (int)$s['id']; ?>">Gallery</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this section?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="id" value="<?php echo (int)$s['id']; ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php admin_layout_end();
